class Solution {
  public int minJumps(int[] nums) {
    int n = nums.length, max = 2;
    for (int x : nums) max = Math.max(max, x);
    int[] spf = new int[max + 1]; // smallest prime factor
    for (int i = 2; i <= max; i++) {
      if (spf[i] != 0) continue;
      for (int j = i; j <= max; j += i) if (spf[j] == 0) spf[j] = i;
    }
    // indices whose value is divisible by each prime
    Map<Integer, List<Integer>> byPrime = new HashMap<>();
    for (int i = 0; i < n; i++) {
      int x = nums[i];
      while (x > 1) {
        int p = spf[x];
        byPrime.computeIfAbsent(p, k -> new ArrayList<>()).add(i);
        while (x % p == 0) x /= p;
      }
    }
    int[] dist = new int[n];
    Arrays.fill(dist, -1);
    dist[0] = 0;
    Deque<Integer> queue = new ArrayDeque<>();
    queue.add(0);
    while (!queue.isEmpty()) {
      int i = queue.poll();
      if (i == n - 1) return dist[i];
      List<Integer> next = new ArrayList<>();
      if (i + 1 < n) next.add(i + 1);
      if (i > 0) next.add(i - 1);
      int v = nums[i];
      if (v > 1 && spf[v] == v) {
        List<Integer> teleports = byPrime.remove(v); // each prime only needs to fan out once
        if (teleports != null) next.addAll(teleports);
      }
      for (int j : next) {
        if (dist[j] < 0) {
          dist[j] = dist[i] + 1;
          queue.add(j);
        }
      }
    }
    return -1;
  }
}
